Amazon Aurora (PostgreSQL) Global Databa.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component Diagram for Amazon Aurora (PostgreSQL) Global Database

Container_Boundary(aurora_global_db, "Amazon Aurora (PostgreSQL) Global Database") {
    Component(primary_writer, "Primary Cluster Instance (Writer)", "PostgreSQL", "Handles write operations and transactional data for the core e-commerce platform.")
    Component(read_replicas, "Cross-Region Read Replica Instances", "PostgreSQL", "Handles regional read operations and personalized queries to reduce latency.")
    Component(storage_volume, "Aurora Storage Volume", "Distributed Storage", "Provides scalable, replicated storage underlying the Aurora database clusters.")
    Component(extension_manager, "PostgreSQL Extension Manager", "PostgreSQL Extension", "Manages database extensions for specialized functions and data types.")
}

Rel(primary_writer, storage_volume, "Persists transactional data", "PostgreSQL wire protocol")
Rel(read_replicas, storage_volume, "Replicates data globally", "PostgreSQL wire protocol")

@enduml

Amazon ElastiCache (Redis).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_elasticache_redis, "Amazon ElastiCache (Redis)") {
    Component(RedisClusterEngine, "Redis Cluster Engine", "Amazon ElastiCache (Redis OSS) with Primary and Replica nodes", "Multi-AZ caching engine ensuring high availability, failover management, and sub-millisecond latency.")
    Component(SessionStoreModule, "Session Store Module", "Redis Keyspace (`sess:*`) with AWS KMS encryption", "Stores encrypted user sessions and shopping carts for sub-millisecond lookups and zero cart data loss.")
    Component(CatalogueCacheModule, "Catalogue Cache Module", "Redis Keyspace (`cat:*`) with LRU eviction", "Caches product metadata and search facets to support read-heavy catalog operations without cache thrashing.")
}

Rel(SessionStoreModule, RedisClusterEngine, "Operates on primary and replica shards with TLS 1.3 encryption and AOF persistence", "Redis RESP / TLS 1.3")
Rel(CatalogueCacheModule, RedisClusterEngine, "Utilizes LRU eviction policies and multi-AZ replication across shards", "Redis RESP / TLS 1.3")
@enduml
